# EVOLVE-BLOCK-START
"""
Prefix-cache-oriented dataframe reordering.

The implementation preserves all original values, rows, indexes, columns, and
shape. It only permutes source cells within a row and returns the matching
per-row source-column ordering.

A small bounded set of layouts is evaluated using the exact serial Trie reuse
objective for a fixed collection of serialized rows: the sum of longest common
prefix lengths between lexicographically adjacent row strings.
"""

from collections import Counter, defaultdict
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Build a few cheap prefix-sharing layouts and select the best exact score."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe for compatibility with Algorithm callers."""
        self.df = df

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one cell exactly as evaluator-style missing-value normalization."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    def _string_matrix(self, df: pd.DataFrame) -> List[List[str]]:
        """Materialize normalized cell strings once without changing stored values."""
        values = df.to_numpy(dtype=object, copy=False)
        return [[self._cell_string(value) for value in row] for row in values]

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the character LCP using bounded binary-search slice comparisons."""
        limit = min(len(left), len(right))
        if not limit:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    def _trie_score(self, strings: List[str]) -> int:
        """Compute ideal serial Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            total += self._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _serialize(
        cells: List[List[str]],
        orders: List[List[int]],
    ) -> List[str]:
        """Join normalized source-cell strings according to row-specific orders."""
        return [
            "".join(cells[row_id][column] for column in order)
            for row_id, order in enumerate(orders)
        ]

    @staticmethod
    def _resolve_column(name, columns: List) -> int:
        """Resolve a column label exactly, then by unique textual containment."""
        for index, column in enumerate(columns):
            if column == name:
                return index

        text = str(name)
        matches = [
            index for index, column in enumerate(columns)
            if text in str(column)
        ]
        return matches[0] if len(matches) == 1 else -1

    @staticmethod
    def _scores_from_column(values: List[str]) -> Tuple[int, int]:
        """Return pair-repetition and lighter repeated-value scores for one field."""
        counts = Counter(values)
        pair = 0
        light = 0

        for value, count in counts.items():
            if count > 1:
                length = len(value)
                pair += length * count * (count - 1)
                light += length * (count - 1)

        return pair, light

    def _column_ranks(
        self,
        cells: List[List[str]],
    ) -> Tuple[List[int], List[int]]:
        """Rank columns by strong pair repetition and lighter repetition evidence."""
        ncols = len(cells[0])
        pair_scores = [0] * ncols
        light_scores = [0] * ncols

        # Constructing a transposed list once avoids repeatedly indexing every row.
        columns_as_values = list(zip(*cells))

        for column, values in enumerate(columns_as_values):
            pair_scores[column], light_scores[column] = (
                self._scores_from_column(values)
            )

        pair_rank = sorted(
            range(ncols),
            key=lambda column: (-pair_scores[column], column),
        )
        light_rank = sorted(
            range(ncols),
            key=lambda column: (
                -light_scores[column],
                -pair_scores[column],
                column,
            ),
        )
        return pair_rank, light_rank

    def _respect_constraints(
        self,
        desired: List[int],
        columns: List,
        col_merge,
        one_way_dep,
    ) -> List[int]:
        """Convert a desired rank into an order honoring merge and dependency rules."""
        if len(desired) <= 1:
            return list(desired)

        rank = {column: position for position, column in enumerate(desired)}
        used = set()
        units = []

        for group in col_merge or []:
            unit = []
            for name in group:
                column = self._resolve_column(name, columns)
                if column >= 0 and column not in used:
                    unit.append(column)

            if unit:
                unit.sort(key=rank.__getitem__)
                units.append(unit)
                used.update(unit)

        for column in desired:
            if column not in used:
                units.append([column])

        unit_for = {}
        for unit_id, unit in enumerate(units):
            for column in unit:
                unit_for[column] = unit_id

        edges = defaultdict(set)
        indegree = [0] * len(units)

        for dependency in one_way_dep or []:
            if not isinstance(dependency, (tuple, list)) or len(dependency) < 2:
                continue

            before = self._resolve_column(dependency[0], columns)
            after = self._resolve_column(dependency[1], columns)

            if before < 0 or after < 0:
                continue

            source = unit_for[before]
            target = unit_for[after]

            if source != target and target not in edges[source]:
                edges[source].add(target)
                indegree[target] += 1

        priority = [min(rank[column] for column in unit) for unit in units]
        available = [
            unit_id for unit_id, degree in enumerate(indegree)
            if degree == 0
        ]
        chosen = []

        while available:
            available.sort(key=lambda unit_id: (priority[unit_id], unit_id))
            current = available.pop(0)
            chosen.append(current)

            for successor in edges[current]:
                indegree[successor] -= 1
                if indegree[successor] == 0:
                    available.append(successor)

        # A cyclic dependency cannot be completely satisfied. Preserve deterministic
        # candidate priority for the unresolved units rather than dropping columns.
        if len(chosen) < len(units):
            chosen_set = set(chosen)
            chosen.extend(
                sorted(
                    (
                        unit_id for unit_id in range(len(units))
                        if unit_id not in chosen_set
                    ),
                    key=lambda unit_id: (priority[unit_id], unit_id),
                )
            )

        return [
            column
            for unit_id in chosen
            for column in units[unit_id]
        ]

    def _conditional_orders(
        self,
        cells: List[List[str]],
        global_rank: List[int],
        max_depth: int,
        max_nodes: int,
    ) -> List[List[int]]:
        """
        Build a bounded conditional prefix tree.

        Each group selects the remaining field with the largest
        len(value) * count * (count - 1) repetition evidence. Rejected fields are
        scored with counters only; row-list partitions are created only for the
        selected field. This retains conditional layouts while avoiding the former
        dictionary-of-lists allocation for every candidate field in every node.
        """
        nrows = len(cells)
        ncols = len(global_rank)

        if not nrows:
            return []

        orders = [None] * nrows
        candidate_cap = min(ncols, 16)
        expanded = 0
        stack = [(list(range(nrows)), [], list(global_rank), 0)]

        while stack:
            row_ids, prefix, remaining, depth = stack.pop()

            if (
                len(row_ids) <= 1
                or not remaining
                or depth >= max_depth
                or expanded >= max_nodes
            ):
                tail = [column for column in global_rank if column in remaining]
                final_order = prefix + tail
                for row_id in row_ids:
                    orders[row_id] = final_order
                continue

            best_column = -1
            best_score = 0

            for column in remaining[:candidate_cap]:
                counts = Counter(cells[row_id][column] for row_id in row_ids)
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                    if count > 1
                )

                if (
                    score > best_score
                    or (
                        score == best_score
                        and score > 0
                        and (best_column < 0 or column < best_column)
                    )
                ):
                    best_column = column
                    best_score = score

            if best_column < 0 or best_score <= 0:
                tail = [column for column in global_rank if column in remaining]
                final_order = prefix + tail
                for row_id in row_ids:
                    orders[row_id] = final_order
                continue

            groups = defaultdict(list)
            for row_id in row_ids:
                groups[cells[row_id][best_column]].append(row_id)

            expanded += 1
            next_prefix = prefix + [best_column]
            next_remaining = [
                column for column in remaining
                if column != best_column
            ]

            for group_rows in groups.values():
                stack.append(
                    (group_rows, next_prefix, next_remaining, depth + 1)
                )

        fallback = list(global_rank)
        return [order if order is not None else fallback for order in orders]

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Evaluate two global ranks and one bounded conditional rank, returning best.

        All candidates are measured by actual serialized character LCP reuse rather
        than field-level estimates. API stop parameters only bound conditional work;
        they never remove rows, columns, or values.
        """
        nrows, ncols = df.shape

        if ncols == 0:
            return df.copy(), [[] for _ in range(nrows)]
        if nrows == 0:
            return df.copy(), []

        columns = list(df.columns)
        cells = self._string_matrix(df)
        pair_rank, light_rank = self._column_ranks(cells)

        global_pair = self._respect_constraints(
            pair_rank, columns, col_merge, one_way_dep
        )
        global_light = self._respect_constraints(
            light_rank, columns, col_merge, one_way_dep
        )

        depth_limit = min(ncols, 6)
        if col_stop is not None and col_stop > 0:
            depth_limit = min(depth_limit, int(col_stop))
        if row_stop is not None and row_stop > 0:
            depth_limit = min(depth_limit, int(row_stop))
        depth_limit = max(1, depth_limit)

        conditional_raw = self._conditional_orders(
            cells,
            pair_rank,
            max_depth=depth_limit,
            max_nodes=64,
        )

        constraint_cache = {}
        conditional = []

        for order in conditional_raw:
            key = tuple(order)
            resolved = constraint_cache.get(key)

            if resolved is None:
                resolved = self._respect_constraints(
                    order, columns, col_merge, one_way_dep
                )
                constraint_cache[key] = resolved

            conditional.append(resolved)

        candidates = [
            [global_pair] * nrows,
            [global_light] * nrows,
            conditional,
        ]

        best_orders = candidates[0]
        best_score = -1

        for orders in candidates:
            score = self._trie_score(self._serialize(cells, orders))
            if score > best_score:
                best_score = score
                best_orders = orders

        source_values = df.to_numpy(dtype=object, copy=False)
        global_layout = all(order == best_orders[0] for order in best_orders)

        if global_layout:
            output_values = source_values[:, best_orders[0]].copy()
        else:
            output_values = np.empty((nrows, ncols), dtype=object)
            for row_id, order in enumerate(best_orders):
                output_values[row_id, :] = source_values[row_id, order]

        result = pd.DataFrame(
            output_values,
            index=df.index.copy(),
            columns=df.columns.copy(),
        )

        column_orderings = [
            [columns[column] for column in order]
            for order in best_orders
        ]

        return result, column_orderings


# EVOLVE-BLOCK-END
